const fruits = [{ name: "maçã", color: "red" }];

function firstRed(): string {
  for (const fruit of fruits) {
    if (fruit.color === "red") {
      return fruit.name;
    }
  }
  return "nenhuma";
}

const players = [{ name: "Ana", points: 3 }, { name: "Bia", points: 5 }];
let best = "";
let bestPoints = 0;
for (const p of players) {
  if (p.points > bestPoints) {
    best = p.name;
    bestPoints = p.points;
  }
}
// best === "Bia"
